public class Solution {
    public static void main(String[] args) {
        int x = 5;
        int y = 10;

        // Step 1: ++x increments x to 6 and yields 6
        // Step 2: y-- yields 10, then decrements y to 9
        // Result: 6 + 10 = 16
        int result1 = ++x + y--;
        System.out.println("result1 (++x + y--): " + result1);
        System.out.println("State after expr 1: x = " + x + ", y = " + y);

        // Step 3: x++ yields 6, then increments x to 7
        // Step 4: --y decrements y to 8 and yields 8
        // Result: 6 + 8 = 14
        int result2 = x++ + --y;
        System.out.println("result2 (x++ + --y): " + result2);
        System.out.println("State after expr 2: x = " + x + ", y = " + y);
    }
}

