    }
}

public class Solution {
    public static void main(String[] args) {
        byte b = 10;

        // b = b + 500; // Compile-time error: incompatible types (int cannot be converted to byte)
        b += 500; // Compiles because javac desugars this to: b = (byte)(b + 500)
        System.out.println("Byte value after compound assignment (b += 500): " + b);

        byte explicitCasted = 10;
        explicitCasted = (byte) (explicitCasted + 500);
        System.out.println("Byte value with explicit cast ((byte)(b + 500)): " + explicitCasted);
    }
}

public class Solution {
    public static boolean checkFirst() {
        System.out.println("-> checkFirst() invoked: returns false");
        return false;
    }

    public static boolean checkSecond() {
        System.out.println("-> checkSecond() invoked: returns true");
        return true;
    }

    public static void main(String[] args) {
        System.out.println("Testing short-circuit AND (&&):");
        boolean scResult = checkFirst() && checkSecond();
        System.out.println("Short-circuit result: " + scResult);

        System.out.println("\nTesting non-short-circuit AND (&):");
        boolean nonScResult = checkFirst() & checkSecond();
        System.out.println("Non-short-circuit result: " + nonScResult);
    }
}

