        boolean scResult = primaryCheck() || secondaryCheck();
        System.out.println("Short-circuit result: " + scResult);

        System.out.println("\nTesting non-short-circuit OR (|):");
        boolean nonScResult = primaryCheck() | secondaryCheck();
        System.out.println("Non-short-circuit result: " + nonScResult);
    }
}

