public class Solution {
    public static boolean getBit(int num, int i) {
        return (num & (1 << i)) != 0;
    }

    public static int setBit(int num, int i) {
        return num | (1 << i);
    }

    public static int clearBit(int num, int i) {
        return num & ~(1 << i);
    }

    public static int toggleBit(int num, int i) {
        return num ^ (1 << i);
    }

    public static void main(String[] args) {
        int num = 8; // Binary: 0000 1000 (bit 3 is set)
        System.out.println("Original: " + num + " (" + Integer.toBinaryString(num) + ")");
        System.out.println("Bit 3 is set: " + getBit(num, 3));
        System.out.println("Bit 1 is set: " + getBit(num, 1));

        num = setBit(num, 1); // Set bit 1 -> 1010 (10)
        System.out.println("After setBit(1): " + num + " (" + Integer.toBinaryString(num) + ")");

        num = clearBit(num, 3); // Clear bit 3 -> 0010 (2)
        System.out.println("After clearBit(3): " + num + " (" + Integer.toBinaryString(num) + ")");

        num = toggleBit(num, 0); // Toggle bit 0 -> 0011 (3)
        System.out.println("After toggleBit(0): " + num + " (" + Integer.toBinaryString(num) + ")");
    }
}

public class Solution {
    public static boolean isPowerOfTwo(int n) {
        return (n > 0) && ((n & (n - 1)) == 0);
    }

    public static void main(String[] args) {
        int[] testValues = {0, 1, 2, 16, 18, 64, 100};
        for (int v : testValues) {
            System.out.println(v + " is power of 2: " + isPowerOfTwo(v));
        }
    }
}

public class Solution {
    public static final byte READ = 1 << 0;    // 0001 (1)
    public static final byte WRITE = 1 << 1;   // 0010 (2)
    public static final byte EXECUTE = 1 << 2; // 0100 (4)
    public static final byte ADMIN = 1 << 3;   // 1000 (8)

    public static void main(String[] args) {
        byte userPermissions = 0;

        // Grant READ and WRITE
        userPermissions |= (READ | WRITE);
        System.out.println("Has READ: " + ((userPermissions & READ) != 0));
        System.out.println("Has WRITE: " + ((userPermissions & WRITE) != 0));
        System.out.println("Has ADMIN: " + ((userPermissions & ADMIN) != 0));

        // Revoke WRITE
        userPermissions &= ~WRITE;
        System.out.println("After revoking WRITE, has WRITE: " + ((userPermissions & WRITE) != 0));

        // Toggle EXECUTE
        userPermissions ^= EXECUTE;
        System.out.println("After toggling EXECUTE, has EXECUTE: " + ((userPermissions & EXECUTE) != 0));
    }
}

