}

public class Solution {
    public static void main(String[] args) {
        int a = 15;
        int b = 42;

        System.out.println("Before XOR swap: a = " + a + ", b = " + b);
        a = a ^ b;
        b = a ^ b;
        a = a ^ b;
        System.out.println("After XOR swap:  a = " + a + ", b = " + b);

        // Edge case demonstration: swapping an element with itself
        int[] arr = {99};
        // arr[0] = arr[0] ^ arr[0] would zero the value out!
        System.out.println("Caution: Same-reference XOR swap zeroes value: (99 ^ 99) = " + (arr[0] ^ arr[0]));
    }
}

public class Solution {
    static int callCountA = 0;
    static int callCountB = 0;

    public static boolean stepA() {
        callCountA++;
        return false;
    }

    public static boolean stepB() {
        callCountB++;
        return true;
    }

    public static void main(String[] args) {
        // Short-circuit && skips stepB
        boolean r1 = stepA() && stepB();
        System.out.println("After short-circuit &&:");
        System.out.println("callCountA = " + callCountA + ", callCountB = " + callCountB);

        // Non-short-circuit & executes both
        boolean r2 = stepA() & stepB();
        System.out.println("\nAfter non-short-circuit &:");
        System.out.println("callCountA = " + callCountA + ", callCountB = " + callCountB);
    }
}

public class Solution {
    public static int countSetBits(int n) {
        int count = 0;
        while (n != 0) {
            n = n & (n - 1); // Clears the lowest set bit
            count++;
        }
        return count;
    }

    public static void main(String[] args) {
        int num = 29; // Binary: 0001 1101 (4 set bits)
        System.out.println("Number: " + num + " (" + Integer.toBinaryString(num) + ")");
        System.out.println("Set bits (Kernighan's): " + countSetBits(num));
        System.out.println("Set bits (Library match): " + Integer.bitCount(num));
    }
}

public class Solution {
    public static void main(String[] args) {
        // Arithmetic swap demonstration
        int a = 100, b = 200;
        System.out.println("Initial: a = " + a + ", b = " + b);
        a = a + b; // Risk of overflow if values are near Integer.MAX_VALUE
        b = a - b;
        a = a - b;
        System.out.println("After arithmetic swap: a = " + a + ", b = " + b);

        // XOR swap demonstration
        int x = 100, y = 200;
        x = x ^ y; // Safe from arithmetic overflow
        y = x ^ y;
        x = x ^ y;
        System.out.println("After XOR swap: x = " + x + ", y = " + y);
    }
}

public class Solution {
    public static void main(String[] args) {
        int negativeNum = -16;
        int arithmeticShift = negativeNum >> 2;
        int logicalShift = negativeNum >>> 2;

        System.out.println("Original value: " + negativeNum);
        System.out.println("Binary original:   " + Integer.toBinaryString(negativeNum));
        System.out.println("Arithmetic (>> 2): " + arithmeticShift + " -> Binary: " + Integer.toBinaryString(arithmeticShift));
        System.out.println("Logical   (>>> 2): " + logicalShift + " -> Binary: " + Integer.toBinaryString(logicalShift));
    }
}
